+fn truncate_utf8_prefix(data: &[u8], length: usize) -> &[u8] {
+    let mut end = length.min(data.len());
+    while end > 0 && end < data.len() && (data[end] & 0xC0) == 0x80 { end -= 1; }
+    &data[..end]
+}
+fn increment_char_same_len(c: char) -> Option<char> {
+    let len = c.len_utf8();
+    let mut cp = c as u32;
+    loop {
+        cp += 1;
+        if cp > char::MAX as u32 { return None; }
+        if let Some(next) = char::from_u32(cp) { return (next.len_utf8()==len).then_some(next); }
+    }
+}
+fn truncate_utf8_max(data: &[u8], length: usize) -> Option<Vec<u8>> {
+    let prefix = truncate_utf8_prefix(data, length);
+    let s = std::str::from_utf8(prefix).ok()?;
+    let mut chars: Vec<char> = s.chars().collect();
+    while let Some(&last) = chars.last() {
+        if let Some(next) = increment_char_same_len(last) {
+            *chars.last_mut().unwrap() = next;
+            let mut out = String::new(); out.extend(chars.iter());
+            return Some(out.into_bytes());
+        }
+        chars.pop();
+    }
+    None
+}
+fn truncate_binary_max(data: &[u8], length: usize) -> Option<Vec<u8>> {
+    let limit = length.min(data.len());
+    for i in (0..limit).rev() { if data[i]!=0xFF { let mut o=data[..=i].to_vec(); o[i]+=1; return Some(o);} }
+    for i in limit..data.len() { if data[i]!=0xFF { let mut o=data[..=i].to_vec(); o[i]+=1; return Some(o);} }
+    None
+}
+fn main() {
+    // min: 100 A -> 64 A
+    let a100 = vec![b'A';100];
+    assert_eq!(truncate_utf8_prefix(&a100,64).len(),64);
+    // min: 63 A + é -> 63 A
+    let mut v = vec![b'A';63]; v.extend_from_slice("é".as_bytes());
+    assert_eq!(truncate_utf8_prefix(&v,64), &vec![b'A';63][..]);
+    // max: 100 A -> 63 A + B
+    let m = truncate_utf8_max(&a100,64).unwrap();
+    let mut exp = vec![b'A';63]; exp.push(b'B');
+    assert_eq!(m, exp, "utf8 max 100A");
+    // max: 33 é truncated to 64 -> 31 é + ê
+    let e33: Vec<u8> = "é".repeat(33).into_bytes();
+    let m2 = truncate_utf8_max(&e33,64).unwrap();
+    let mut exp2 = "é".repeat(31).into_bytes(); exp2.extend_from_slice("ê".as_bytes());
+    assert_eq!(m2, exp2, "utf8 max 33é");
+    // binary max example
+    let mut d = vec![0xFFu8;8]; d.push(0x00); d.extend(vec![0xFFu8;6]);
+    let bm = truncate_binary_max(&d,1).unwrap();
+    let mut expb = vec![0xFFu8;8]; expb.push(0x01);
+    assert_eq!(bm, expb, "binary max FF");
+    println!("ALL OK; é len={} ê={:?}", "é".len(), "ê".as_bytes());
+}
