+import io, os, polars as pl
+import pyarrow.parquet as pq
+
+def stats(df, **kw):
+    buf = io.BytesIO()
+    df.write_parquet(buf, **kw)
+    size = buf.tell()
+    buf.seek(0)
+    md = pq.read_metadata(buf)
+    s = md.row_group(0).column(0).statistics
+    return size, s
+
+big = "A" * 1_000_000
+# 1. string huge value -> small file
+size, s = stats(pl.DataFrame({"a":[big]}))
+print("string size", size, "min_len", len(s.min), "max", s.max[:5], len(s.max))
+assert size < 5000, size
+assert len(s.min) == 64 and s.min == "A"*64
+assert len(s.max) == 64 and s.max == "A"*63+"B"
+
+# 2. binary huge value
+size, s = stats(pl.DataFrame({"a":[big.encode()]}, schema={"a":pl.Binary}))
+print("binary size", size, "min_len", len(s.min), len(s.max))
+assert size < 5000
+assert s.min == b"A"*64
+assert s.max == b"A"*63+b"B"
+
+# 3. short value unchanged
+size, s = stats(pl.DataFrame({"a":["hello"]}))
+print("short", s.min, s.max)
+assert s.min == "hello" and s.max == "hello"
+
+# 4. disable via env=0
+os.environ["POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN"]="0"
+size, s = stats(pl.DataFrame({"a":[big]}))
+print("disabled len", len(s.min))
+assert len(s.min)==1_000_000
+
+# 5. custom N
+os.environ["POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN"]="10"
+size, s = stats(pl.DataFrame({"a":[big]}))
+print("N=10", len(s.min), len(s.max))
+assert len(s.min)==10 and s.min=="A"*10
+del os.environ["POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN"]
+
+# 6. large_utf8 via arrow
+import pyarrow as pa
+tbl = pa.table({"a": pa.array([big], type=pa.large_string())})
+df = pl.from_arrow(tbl)
+size, s = stats(df)
+print("large_utf8", df.dtypes, size, len(s.min))
+assert size < 5000
+
+print("ALL PYTHON CHECKS PASSED")
